import fs from 'node:fs';
import ts from 'typescript';

const files = process.argv.slice(2);

function specifierText(el) {
    // el: ImportSpecifier, isTypeOnly already stripped by caller
    if (el.propertyName) {
        return `${el.propertyName.text} as ${el.name.text}`;
    }
    return el.name.text;
}

for (const file of files) {
    const original = fs.readFileSync(file, 'utf8');
    const sourceFile = ts.createSourceFile(
        file,
        original,
        ts.ScriptTarget.Latest,
        true,
        file.endsWith('.tsx') ? ts.ScriptKind.TSX : ts.ScriptKind.TS,
    );

    const edits = [];

    sourceFile.forEachChild((node) => {
        if (!ts.isImportDeclaration(node)) return;
        const clause = node.importClause;
        if (!clause || !clause.namedBindings) return;
        if (!ts.isNamedImports(clause.namedBindings)) return;
        if (clause.isTypeOnly) return; // whole import already `import type {...}`

        const elements = clause.namedBindings.elements;
        const hasInlineType = elements.some((el) => el.isTypeOnly);
        if (!hasInlineType) return;

        const typeSpecs = elements
            .filter((el) => el.isTypeOnly)
            .map(specifierText);
        const valueSpecs = elements
            .filter((el) => !el.isTypeOnly)
            .map(specifierText);

        const moduleText = node.moduleSpecifier.getText(sourceFile);
        const defaultName = clause.name ? clause.name.text : null;

        const statements = [];
        if (typeSpecs.length > 0) {
            statements.push(
                `import type { ${typeSpecs.join(', ')} } from ${moduleText};`,
            );
        }
        if (valueSpecs.length > 0 || defaultName) {
            const parts = [];
            if (defaultName) parts.push(defaultName);
            if (valueSpecs.length > 0)
                parts.push(`{ ${valueSpecs.join(', ')} }`);
            statements.push(
                `import ${parts.join(', ')} from ${moduleText};`,
            );
        }

        edits.push({
            start: node.getStart(sourceFile),
            end: node.getEnd(),
            text: statements.join('\n'),
        });
    });

    if (edits.length === 0) {
        console.log(`no change: ${file}`);
        continue;
    }

    edits.sort((a, b) => b.start - a.start);
    let out = original;
    for (const e of edits) {
        out = out.slice(0, e.start) + e.text + out.slice(e.end);
    }
    fs.writeFileSync(file, out);
    console.log(`updated (${edits.length}): ${file}`);
}

